#!/usr/bin/env bash

# NOTE: Initial file generated by Claude Sonnet 5.5.

set -euo pipefail

# shellcheck source=load-env.sh
source /usr/local/bin/load-env.sh

# Optional config file of KEY=VALUE lines. Values already present in the
# environment take precedence over the file.
CONFIG_FILE="${ZOCALO_ENV_FILE:-/zocalo.env}"
if [ -f "$CONFIG_FILE" ]; then
  load_env_file "$CONFIG_FILE"
fi

: "${DOMAIN:?DOMAIN must be set}"

# Let's Encrypt cannot issue certificates for "localhost"; in that case CertBot is
# skipped and Caddy's internal CA issues the certificate instead.
if [ "$DOMAIN" = "localhost" ]; then
  IS_LOCAL=1
else
  IS_LOCAL=0
  : "${CERTBOT_EMAIL:?CERTBOT_EMAIL must be set when DOMAIN is not localhost}"
fi

# Must match DB_NAME used when the image was built (it is compiled into the binary).
DB_NAME="${DB_NAME:-zocalo}"
PGDATA=/usr/local/pgsql/data
PGBIN="$(ls -d /usr/lib/postgresql/*/bin | sort -V | tail -n 1)"
CERT_DIR="/etc/letsencrypt/live/${DOMAIN}"
CADDYFILE=/etc/caddy/Caddyfile

pids=()
cleanup() {
  for pid in "${pids[@]:-}"; do kill "$pid" 2>/dev/null || true; done
  su postgres -c "${PGBIN}/pg_ctl stop -D ${PGDATA} -m fast" 2>/dev/null || true
}
trap cleanup EXIT TERM INT

# --- Postgres ---------------------------------------------------------------
chown -R postgres:postgres "$PGDATA"
chmod 700 "$PGDATA"
if [ ! -f "${PGDATA}/PG_VERSION" ]; then
  su postgres -c "${PGBIN}/initdb -D ${PGDATA} --encoding=UTF8 --auth=trust"
fi
su postgres -c "${PGBIN}/pg_ctl start -w -D ${PGDATA} -l /usr/local/pgsql/log/logfile.log -o '-c listen_addresses=127.0.0.1'"

if ! su postgres -c "psql -tAc \"SELECT 1 FROM pg_database WHERE datname='${DB_NAME}'\"" | grep -q 1; then
  su postgres -c "psql -c \"CREATE DATABASE ${DB_NAME} WITH ENCODING='UTF8' CONNECTION LIMIT=-1;\""
fi

# --- CertBot ----------------------------------------------------------------
# Standalone mode needs port 80, which Caddy does not bind (its site is ":443").
STAGING_FLAG=()
[ "${CERTBOT_STAGING:-0}" = "1" ] && STAGING_FLAG=(--staging)

if [ "$IS_LOCAL" = "0" ] && [ ! -f "${CERT_DIR}/fullchain.pem" ]; then
  certbot certonly --standalone --non-interactive --agree-tos \
    -m "$CERTBOT_EMAIL" -d "$DOMAIN" "${STAGING_FLAG[@]}"
fi

# --- Caddy ------------------------------------------------------------------
if [ "$IS_LOCAL" = "1" ]; then
  cat > "$CADDYFILE" <<EOF
localhost:443 {
  tls internal
  reverse_proxy 127.0.0.1:8000
}
EOF
else
  cat > "$CADDYFILE" <<EOF
:443 {
  tls ${CERT_DIR}/fullchain.pem ${CERT_DIR}/privkey.pem
  reverse_proxy 127.0.0.1:8000
}
EOF
fi

caddy run --config "$CADDYFILE" --adapter caddyfile &
pids+=($!)

# Renewal loop: twice a day; reload Caddy only when a cert was actually renewed.
if [ "$IS_LOCAL" = "0" ]; then
(
  while true; do
    sleep 12h
    certbot renew --standalone --non-interactive \
      --deploy-hook "caddy reload --config ${CADDYFILE} --adapter caddyfile" || true
  done
) &
pids+=($!)
fi

# --- Application ------------------------------------------------------------
cd /app
run-zocalo &
pids+=($!)
wait -n
